package com.enterprise.licensing.engine.cache;
import com.enterprise.licensing.crypto.CanonicalJson;import com.enterprise.licensing.engine.activation.LicenseRepository;import com.enterprise.licensing.engine.identity.LicenseServerIdentityService;import com.enterprise.licensing.engine.instance.ProductInstanceRepository;import com.enterprise.licensing.engine.ports.*;import com.enterprise.licensing.engine.validation.OperationAuthorizer;import com.enterprise.licensing.model.*;import java.time.*;import java.util.List;import java.util.Set;
public final class CachedEntitlementService{private static final Set<LicenseOperation>DEFAULT=Set.of(LicenseOperation.PRODUCT_CHECK,LicenseOperation.FEATURE_CHECK);private final LicenseRepository licenses;private final ProductInstanceRepository instances;private final LicenseServerIdentityService identity;private final CachedEntitlementRepository repository;private final TimeSource time;private final IdGenerator ids;private final Duration maximum;private final CanonicalJson canonical;private final OperationAuthorizer authorizer;
 public CachedEntitlementService(LicenseRepository l,ProductInstanceRepository i,LicenseServerIdentityService s,CachedEntitlementRepository r,TimeSource t,IdGenerator ids,Duration max,CanonicalJson c,OperationAuthorizer v){licenses=l;instances=i;identity=s;repository=r;time=t;this.ids=ids;maximum=max;canonical=c;authorizer=v;}
 public CachedEntitlementResult issue(String instanceId){var authorization=authorizer.evaluate(LicenseOperation.CACHED_ENTITLEMENT_ISSUE);if(!authorization.allowed())return CachedEntitlementResult.denied(authorization.reasonCode());var state=licenses.active().orElse(null);if(state==null)return CachedEntitlementResult.denied(LicenseReasonCode.LICENSE_SERVER_NOT_ACTIVATED);var instance=instances.find(instanceId).orElse(null);if(instance==null||instance.state()!=InstanceState.ACTIVE)return CachedEntitlementResult.denied(LicenseReasonCode.INSTANCE_NOT_REGISTERED);var product=state.license().products().stream().filter(p->p.id().equals(instance.productId())&&p.enabled()).findFirst().orElse(null);if(product==null)return CachedEntitlementResult.denied(LicenseReasonCode.PRODUCT_NOT_ENTITLED);Instant now=time.now();Instant expiry=min(now.plus(maximum),state.license().subscription().graceUntil());if(!expiry.isAfter(now))return CachedEntitlementResult.denied(LicenseReasonCode.LICENSE_EXPIRED);var certificate=new CachedEntitlementCertificate("1.0",ids.next().toString(),state.license().licenseId(),identity.publicIdentity().licenseServerId().toString(),instanceId,instance.publicKeyFingerprint(),now,expiry,List.of(product),DEFAULT);var envelope=identity.signCachedEntitlement(certificate,"1.0",canonical);repository.save(certificate,envelope);return CachedEntitlementResult.accepted(certificate,envelope);}
 private static Instant min(Instant a,Instant b){return a.isBefore(b)?a:b;}}
